CREATE TABLE IF NOT EXISTS "organizations" (
	-- Surrogate primary key. This is the tenant id every other table carries.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Display name of the workspace.
	"name" VARCHAR(160) NOT NULL,
	-- URL and subdomain segment, unique across all tenants.
	"slug" VARCHAR(80) NOT NULL UNIQUE,
	-- Current plan. Null only during signup, before a plan is chosen.
	"plan_id" BIGINT,
	-- End of the free trial. Null once converted or never trialled.
	"trial_ends_at" TIMESTAMP,
	-- Seats paid for. Compared against active memberships to block over-assignment.
	"seats_purchased" INTEGER NOT NULL DEFAULT 1,
	-- Workspace creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Soft-delete marker. Retained so billing and audit history survive a cancellation.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "organizations" IS 'The tenant. Every tenant-scoped table carries organization_id, and every query filters on it — with row-level security enforcing that filter rather than trusting application code.';
COMMENT ON COLUMN "organizations"."id" IS 'Surrogate primary key. This is the tenant id every other table carries.';
COMMENT ON COLUMN "organizations"."name" IS 'Display name of the workspace.';
COMMENT ON COLUMN "organizations"."slug" IS 'URL and subdomain segment, unique across all tenants.';
COMMENT ON COLUMN "organizations"."plan_id" IS 'Current plan. Null only during signup, before a plan is chosen.';
COMMENT ON COLUMN "organizations"."trial_ends_at" IS 'End of the free trial. Null once converted or never trialled.';
COMMENT ON COLUMN "organizations"."seats_purchased" IS 'Seats paid for. Compared against active memberships to block over-assignment.';
COMMENT ON COLUMN "organizations"."created_at" IS 'Workspace creation time.';
COMMENT ON COLUMN "organizations"."deleted_at" IS 'Soft-delete marker. Retained so billing and audit history survive a cancellation.';

CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Global login identity. A user exists once and belongs to many organizations.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name.
	"full_name" VARCHAR(160) NOT NULL,
	-- Argon2id hash. Null for SSO-only accounts.
	"password_hash" VARCHAR(255),
	-- Set when the address is confirmed.
	"email_verified_at" TIMESTAMP,
	-- Most recent successful sign-in.
	"last_login_at" TIMESTAMP,
	-- Account creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person, not a tenant member. Keeping users global is what lets one account switch between a personal workspace and an employer workspace without a second password.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Global login identity. A user exists once and belongs to many organizations.';
COMMENT ON COLUMN "users"."full_name" IS 'Display name.';
COMMENT ON COLUMN "users"."password_hash" IS 'Argon2id hash. Null for SSO-only accounts.';
COMMENT ON COLUMN "users"."email_verified_at" IS 'Set when the address is confirmed.';
COMMENT ON COLUMN "users"."last_login_at" IS 'Most recent successful sign-in.';
COMMENT ON COLUMN "users"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "memberships" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Tenant the user belongs to.
	"organization_id" BIGINT NOT NULL,
	-- The member.
	"user_id" BIGINT NOT NULL,
	-- owner | admin | member | viewer. Authorisation is resolved from this, never from a flag on users.
	"role" VARCHAR(24) NOT NULL DEFAULT 'member',
	-- active | suspended. Suspended members keep their history but cannot sign in to the tenant.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- When the invitation was accepted.
	"joined_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "memberships" IS 'The join table that makes the product multi-tenant. Role lives here because the same person can be an owner in one workspace and a viewer in another.';
COMMENT ON COLUMN "memberships"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "memberships"."organization_id" IS 'Tenant the user belongs to.';
COMMENT ON COLUMN "memberships"."user_id" IS 'The member.';
COMMENT ON COLUMN "memberships"."role" IS 'owner | admin | member | viewer. Authorisation is resolved from this, never from a flag on users.';
COMMENT ON COLUMN "memberships"."status" IS 'active | suspended. Suspended members keep their history but cannot sign in to the tenant.';
COMMENT ON COLUMN "memberships"."joined_at" IS 'When the invitation was accepted.';

CREATE UNIQUE INDEX "uq_memberships_org_user"
ON "memberships" ("organization_id", "user_id");
CREATE INDEX "idx_memberships_org_role"
ON "memberships" ("organization_id", "role");

CREATE TABLE IF NOT EXISTS "invitations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Tenant the invitee is being added to.
	"organization_id" BIGINT NOT NULL,
	-- Member who sent the invitation. Null if that member was later deleted.
	"invited_by_user_id" BIGINT,
	-- Invitee address. Deliberately not a user reference — the invitee may not have an account yet.
	"email" VARCHAR(320) NOT NULL,
	-- Role granted on acceptance.
	"role" VARCHAR(24) NOT NULL DEFAULT 'member',
	-- Hash of the single-use acceptance token. The plaintext token is only ever in the email.
	"token_hash" VARCHAR(255) NOT NULL UNIQUE,
	-- Invitation expiry, typically 7 days out.
	"expires_at" TIMESTAMP NOT NULL,
	-- Acceptance time. A non-null value makes the token unusable.
	"accepted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "invitations" IS 'Pending invitations. Storing only the token hash means a leaked database dump cannot be used to join workspaces.';
COMMENT ON COLUMN "invitations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "invitations"."organization_id" IS 'Tenant the invitee is being added to.';
COMMENT ON COLUMN "invitations"."invited_by_user_id" IS 'Member who sent the invitation. Null if that member was later deleted.';
COMMENT ON COLUMN "invitations"."email" IS 'Invitee address. Deliberately not a user reference — the invitee may not have an account yet.';
COMMENT ON COLUMN "invitations"."role" IS 'Role granted on acceptance.';
COMMENT ON COLUMN "invitations"."token_hash" IS 'Hash of the single-use acceptance token. The plaintext token is only ever in the email.';
COMMENT ON COLUMN "invitations"."expires_at" IS 'Invitation expiry, typically 7 days out.';
COMMENT ON COLUMN "invitations"."accepted_at" IS 'Acceptance time. A non-null value makes the token unusable.';

CREATE INDEX "idx_invitations_org_email"
ON "invitations" ("organization_id", "email");

CREATE TABLE IF NOT EXISTS "projects" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning tenant. Present on every tenant-scoped row.
	"organization_id" BIGINT NOT NULL,
	-- Project name.
	"name" VARCHAR(160) NOT NULL,
	-- URL segment, unique within the organization rather than globally.
	"slug" VARCHAR(80) NOT NULL,
	-- Archive marker. Archived projects are hidden but still billable in usage history.
	"archived_at" TIMESTAMP,
	-- Row creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "projects" IS 'Stand-in for whatever the product actually contains. The shape that matters is organization_id plus a slug unique per tenant, not globally.';
COMMENT ON COLUMN "projects"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "projects"."organization_id" IS 'Owning tenant. Present on every tenant-scoped row.';
COMMENT ON COLUMN "projects"."name" IS 'Project name.';
COMMENT ON COLUMN "projects"."slug" IS 'URL segment, unique within the organization rather than globally.';
COMMENT ON COLUMN "projects"."archived_at" IS 'Archive marker. Archived projects are hidden but still billable in usage history.';
COMMENT ON COLUMN "projects"."created_at" IS 'Row creation time.';

CREATE UNIQUE INDEX "uq_projects_org_slug"
ON "projects" ("organization_id", "slug");

CREATE TABLE IF NOT EXISTS "api_keys" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Tenant the key acts on behalf of.
	"organization_id" BIGINT NOT NULL,
	-- Member who issued the key.
	"created_by_user_id" BIGINT,
	-- Human label, e.g. "CI pipeline".
	"name" VARCHAR(80) NOT NULL,
	-- First characters of the key, shown in the UI so a key can be identified without revealing it.
	"key_prefix" VARCHAR(12) NOT NULL,
	-- bcrypt hash of the full key. The plaintext is shown exactly once, at creation.
	"key_hash" VARCHAR(255) NOT NULL UNIQUE,
	-- Updated on use, so stale keys can be found and revoked.
	"last_used_at" TIMESTAMP,
	-- Optional expiry.
	"expires_at" TIMESTAMP,
	-- Revocation time. Revoked keys are kept so audit entries still resolve.
	"revoked_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "api_keys" IS 'Machine credentials scoped to a tenant, not to a user, so an employee leaving does not break the integration they set up.';
COMMENT ON COLUMN "api_keys"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "api_keys"."organization_id" IS 'Tenant the key acts on behalf of.';
COMMENT ON COLUMN "api_keys"."created_by_user_id" IS 'Member who issued the key.';
COMMENT ON COLUMN "api_keys"."name" IS 'Human label, e.g. "CI pipeline".';
COMMENT ON COLUMN "api_keys"."key_prefix" IS 'First characters of the key, shown in the UI so a key can be identified without revealing it.';
COMMENT ON COLUMN "api_keys"."key_hash" IS 'bcrypt hash of the full key. The plaintext is shown exactly once, at creation.';
COMMENT ON COLUMN "api_keys"."last_used_at" IS 'Updated on use, so stale keys can be found and revoked.';
COMMENT ON COLUMN "api_keys"."expires_at" IS 'Optional expiry.';
COMMENT ON COLUMN "api_keys"."revoked_at" IS 'Revocation time. Revoked keys are kept so audit entries still resolve.';

CREATE INDEX "idx_api_keys_org_active"
ON "api_keys" ("organization_id", "revoked_at");

CREATE TABLE IF NOT EXISTS "plans" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable identifier used in code, e.g. team_pro.
	"code" VARCHAR(40) NOT NULL UNIQUE,
	-- Customer-facing plan name.
	"name" VARCHAR(80) NOT NULL,
	-- List price per seat per interval, in minor units.
	"price_cents" INTEGER NOT NULL,
	-- ISO 4217 currency.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- month | year.
	"interval" VARCHAR(12) NOT NULL DEFAULT 'month',
	-- Feature flags and limits for the tier. JSON so adding a limit is not a migration.
	"features" JSON NOT NULL,
	-- False for legacy or negotiated plans that must not appear on the pricing page.
	"is_public" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "plans" IS 'Plan catalogue. Keeping limits in a JSON column on the plan means entitlement checks read one row instead of a hand-maintained switch statement.';
COMMENT ON COLUMN "plans"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "plans"."code" IS 'Stable identifier used in code, e.g. team_pro.';
COMMENT ON COLUMN "plans"."name" IS 'Customer-facing plan name.';
COMMENT ON COLUMN "plans"."price_cents" IS 'List price per seat per interval, in minor units.';
COMMENT ON COLUMN "plans"."currency_code" IS 'ISO 4217 currency.';
COMMENT ON COLUMN "plans"."interval" IS 'month | year.';
COMMENT ON COLUMN "plans"."features" IS 'Feature flags and limits for the tier. JSON so adding a limit is not a migration.';
COMMENT ON COLUMN "plans"."is_public" IS 'False for legacy or negotiated plans that must not appear on the pricing page.';

CREATE TABLE IF NOT EXISTS "subscriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Tenant being billed.
	"organization_id" BIGINT NOT NULL,
	-- Plan in force for this period.
	"plan_id" BIGINT NOT NULL,
	-- Billing provider subscription id, e.g. from Stripe or Paddle.
	"provider_reference" VARCHAR(120) UNIQUE,
	-- trialing | active | past_due | canceled.
	"status" VARCHAR(24) NOT NULL,
	-- Seats billed. Kept in step with seats_purchased on the organization.
	"quantity" INTEGER NOT NULL DEFAULT 1,
	-- Start of the period being billed.
	"current_period_start" TIMESTAMP NOT NULL,
	-- End of the period; drives renewal and dunning.
	"current_period_end" TIMESTAMP NOT NULL,
	-- When cancellation was requested. Access usually continues to period end.
	"canceled_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscriptions" IS 'One row per billing period arrangement. History is preserved by inserting rather than mutating, so a downgrade does not erase what the customer was on last quarter.';
COMMENT ON COLUMN "subscriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscriptions"."organization_id" IS 'Tenant being billed.';
COMMENT ON COLUMN "subscriptions"."plan_id" IS 'Plan in force for this period.';
COMMENT ON COLUMN "subscriptions"."provider_reference" IS 'Billing provider subscription id, e.g. from Stripe or Paddle.';
COMMENT ON COLUMN "subscriptions"."status" IS 'trialing | active | past_due | canceled.';
COMMENT ON COLUMN "subscriptions"."quantity" IS 'Seats billed. Kept in step with seats_purchased on the organization.';
COMMENT ON COLUMN "subscriptions"."current_period_start" IS 'Start of the period being billed.';
COMMENT ON COLUMN "subscriptions"."current_period_end" IS 'End of the period; drives renewal and dunning.';
COMMENT ON COLUMN "subscriptions"."canceled_at" IS 'When cancellation was requested. Access usually continues to period end.';

CREATE INDEX "idx_subscriptions_org_status"
ON "subscriptions" ("organization_id", "status");

CREATE TABLE IF NOT EXISTS "usage_records" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Tenant that consumed the resource.
	"organization_id" BIGINT NOT NULL,
	-- What is being counted, e.g. api_calls or seats_active.
	"metric" VARCHAR(40) NOT NULL,
	-- Units consumed in the window.
	"quantity" INTEGER NOT NULL,
	-- Start of the aggregation window, typically an hour or a day.
	"window_start" TIMESTAMP NOT NULL,
	-- When the row was written.
	"recorded_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "usage_records" IS 'Pre-aggregated usage. The unique key makes the writer idempotent: a retried batch job overwrites its own window instead of double counting.';
COMMENT ON COLUMN "usage_records"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "usage_records"."organization_id" IS 'Tenant that consumed the resource.';
COMMENT ON COLUMN "usage_records"."metric" IS 'What is being counted, e.g. api_calls or seats_active.';
COMMENT ON COLUMN "usage_records"."quantity" IS 'Units consumed in the window.';
COMMENT ON COLUMN "usage_records"."window_start" IS 'Start of the aggregation window, typically an hour or a day.';
COMMENT ON COLUMN "usage_records"."recorded_at" IS 'When the row was written.';

CREATE UNIQUE INDEX "uq_usage_org_metric_window"
ON "usage_records" ("organization_id", "metric", "window_start");

CREATE TABLE IF NOT EXISTS "audit_logs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Tenant the action happened in.
	"organization_id" BIGINT NOT NULL,
	-- Member who acted. Null for system or API-key actions.
	"actor_user_id" BIGINT,
	-- API key that acted, when the actor was a machine.
	"actor_api_key_id" BIGINT,
	-- Verb and subject, e.g. project.deleted.
	"action" VARCHAR(80) NOT NULL,
	-- Entity type acted on.
	"target_type" VARCHAR(60),
	-- Identifier of the entity acted on, as text so any table can be referenced.
	"target_id" VARCHAR(64),
	-- Before/after values or request context.
	"metadata" JSON,
	-- Source address, long enough for IPv6.
	"ip_address" VARCHAR(45),
	-- Event time. Rows are never updated or deleted.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "audit_logs" IS 'Append-only activity trail. Enterprise buyers ask for this in security review, and it is far cheaper to write from day one than to reconstruct later.';
COMMENT ON COLUMN "audit_logs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "audit_logs"."organization_id" IS 'Tenant the action happened in.';
COMMENT ON COLUMN "audit_logs"."actor_user_id" IS 'Member who acted. Null for system or API-key actions.';
COMMENT ON COLUMN "audit_logs"."actor_api_key_id" IS 'API key that acted, when the actor was a machine.';
COMMENT ON COLUMN "audit_logs"."action" IS 'Verb and subject, e.g. project.deleted.';
COMMENT ON COLUMN "audit_logs"."target_type" IS 'Entity type acted on.';
COMMENT ON COLUMN "audit_logs"."target_id" IS 'Identifier of the entity acted on, as text so any table can be referenced.';
COMMENT ON COLUMN "audit_logs"."metadata" IS 'Before/after values or request context.';
COMMENT ON COLUMN "audit_logs"."ip_address" IS 'Source address, long enough for IPv6.';
COMMENT ON COLUMN "audit_logs"."created_at" IS 'Event time. Rows are never updated or deleted.';

CREATE INDEX "idx_audit_org_created"
ON "audit_logs" ("organization_id", "created_at");
CREATE INDEX "idx_audit_org_action"
ON "audit_logs" ("organization_id", "action");

ALTER TABLE "organizations"
ADD FOREIGN KEY("plan_id") REFERENCES "plans"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "memberships"
ADD FOREIGN KEY("organization_id") REFERENCES "organizations"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "memberships"
