ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "invitations"
ADD FOREIGN KEY("organization_id") REFERENCES "organizations"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "invitations"
ADD FOREIGN KEY("invited_by_user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "projects"
ADD FOREIGN KEY("organization_id") REFERENCES "organizations"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "api_keys"
ADD FOREIGN KEY("organization_id") REFERENCES "organizations"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "api_keys"
ADD FOREIGN KEY("created_by_user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "subscriptions"
ADD FOREIGN KEY("organization_id") REFERENCES "organizations"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "subscriptions"
ADD FOREIGN KEY("plan_id") REFERENCES "plans"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "usage_records"
ADD FOREIGN KEY("organization_id") REFERENCES "organizations"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "audit_logs"
ADD FOREIGN KEY("organization_id") REFERENCES "organizations"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "audit_logs"
ADD FOREIGN KEY("actor_user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "audit_logs"
ADD FOREIGN KEY("actor_api_key_id") REFERENCES "api_keys"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
